$(document).ready(function(b){$(".nav.fr ul li a").removeClass("current").eq(2).addClass("current");var a=getUrlParameter("type");a=removeSpecialStr(a);a=a.replace("#","");if(a!=null&&a=="news"){$("#pageContext").html("< 公司公告").attr("href","/AppService/article/newsList.shtml?type=2")}if(a=="original"){$("#pageContext").html("< 原创文章").attr("href","/AppService/article/newsList.shtml?type=3")}if(a=="publicity"){$("#pageContext").html("< 信息公示").attr("href","/AppService/article/infoPublicity.shtml");$(".nav.fr ul li a").removeClass("current").eq(5).addClass("current")}queryArticleContent();document.title="招商财富_"+$("#title").text();console.log("1")});function queryArticleContent(){var a=getUrlParameter("articleId");a=removeSpecialStr(a);$.ajax({async:false,url:"/AppService/article/queryArticleContent.xhtml",data:{articleId:a},dataType:"json",cache:false,type:"post",error:function(c,b){},success:function(b){$("#title").html(b.title);$("#publishDate").html(b.publishDate);$("#content").html(b.content)}})}function queryHotFundByType(){var a=getUrlParameter("articleId");a=removeSpecialStr(a);$.ajax({async:false,url:"/AppService/article/queryHotFundByType.xhtml",data:{},dataType:"json",cache:false,type:"post",error:function(c,b){},success:function(b){var c=b.fundInfoDtoV2;if(c!=null){$("#fundLink").attr("href","/AppService/business/fund/fundDetail.shtml?fundid="+c.fundId);$("#adname").html(c.adname);$("#profit").html("<em>"+parseInt(numMulti(c.profit,100),10)+"</em><b></b><i>%</i><span>+</span>")}}})}$(document).ready(function(a){$("#content img").each(function(){var c=$(this);var b=new Image();b.src=$(this).attr("src");b.onload=function(){if(c.width()>656){c.css("width","100%")}}})});